-- 2026-11-23: refill the carry-forward columns that the contract-id re-mint blanked on the 21
-- restored DEALs (see ext_overwrite_cid_restore_20261123.sql). Fill-if-empty only.
-- Source: the DEAL's own row in all_CH_Deal_sheet_data first; for contract-level columns fall back
-- to the run-rate row of the restored id. Placement-specific columns (BACKOUT_OR_TERMINATION, CLIENT_NAME_IN_CONREP, COMMENTS, ST_DT_PUSHBACK_REASON)
-- come only from the DEAL's own row.

CREATE TABLE IF NOT EXISTS `cynetdatabase.rr_project_data.bkp_20261123_extow_cf_deal_sheet` AS
SELECT t.* FROM `cynetdatabase.rr_project_data.cynet_health_deal_sheet` t
WHERE CAST(t.PLACEMENT_ID AS STRING) IN (SELECT pid FROM `cynetdatabase.rr_project_data.fix_20261123_ext_overwrite_cid_map`);

UPDATE `cynetdatabase.rr_project_data.cynet_health_deal_sheet` t
SET
  SKU_NUMBER = IF((t.SKU_NUMBER IS NULL OR TRIM(CAST(t.SKU_NUMBER AS STRING))=''), COALESCE(s.SKU_NUMBER, t.SKU_NUMBER), t.SKU_NUMBER),
  CLIENT_RECRUITER = IF((t.CLIENT_RECRUITER IS NULL OR TRIM(CAST(t.CLIENT_RECRUITER AS STRING))=''), COALESCE(s.CLIENT_RECRUITER, t.CLIENT_RECRUITER), t.CLIENT_RECRUITER),
  CREDENTIALING_SPECIALIST = IF((t.CREDENTIALING_SPECIALIST IS NULL OR TRIM(CAST(t.CREDENTIALING_SPECIALIST AS STRING))=''), COALESCE(s.CREDENTIALING_SPECIALIST, t.CREDENTIALING_SPECIALIST), t.CREDENTIALING_SPECIALIST),
  CREDENTIALING_LEAD = IF((t.CREDENTIALING_LEAD IS NULL OR TRIM(CAST(t.CREDENTIALING_LEAD AS STRING))=''), COALESCE(s.CREDENTIALING_LEAD, t.CREDENTIALING_LEAD), t.CREDENTIALING_LEAD),
  PRIMARY_SALES_PERSON = IF((t.PRIMARY_SALES_PERSON IS NULL OR TRIM(CAST(t.PRIMARY_SALES_PERSON AS STRING))=''), COALESCE(s.PRIMARY_SALES_PERSON, t.PRIMARY_SALES_PERSON), t.PRIMARY_SALES_PERSON),
  SECONDARY_SALES_PERSON = IF((t.SECONDARY_SALES_PERSON IS NULL OR TRIM(CAST(t.SECONDARY_SALES_PERSON AS STRING))=''), COALESCE(s.SECONDARY_SALES_PERSON, t.SECONDARY_SALES_PERSON), t.SECONDARY_SALES_PERSON),
  RECRUITMENT_MENTOR = IF((t.RECRUITMENT_MENTOR IS NULL OR TRIM(CAST(t.RECRUITMENT_MENTOR AS STRING))=''), COALESCE(s.RECRUITMENT_MENTOR, t.RECRUITMENT_MENTOR), t.RECRUITMENT_MENTOR),
  INVOICE_CYCLE_TO_CLIENT = IF((t.INVOICE_CYCLE_TO_CLIENT IS NULL OR TRIM(CAST(t.INVOICE_CYCLE_TO_CLIENT AS STRING))=''), COALESCE(s.INVOICE_CYCLE_TO_CLIENT, t.INVOICE_CYCLE_TO_CLIENT), t.INVOICE_CYCLE_TO_CLIENT),
  CLIENT_PAYMENT_TERMS = IF((t.CLIENT_PAYMENT_TERMS IS NULL OR TRIM(CAST(t.CLIENT_PAYMENT_TERMS AS STRING))=''), COALESCE(s.CLIENT_PAYMENT_TERMS, t.CLIENT_PAYMENT_TERMS), t.CLIENT_PAYMENT_TERMS),
  CANDIDATE_PAYMENT_TERMS = IF((t.CANDIDATE_PAYMENT_TERMS IS NULL OR TRIM(CAST(t.CANDIDATE_PAYMENT_TERMS AS STRING))=''), COALESCE(s.CANDIDATE_PAYMENT_TERMS, t.CANDIDATE_PAYMENT_TERMS), t.CANDIDATE_PAYMENT_TERMS),
  SECONDARY_RECRUITER = IF((t.SECONDARY_RECRUITER IS NULL OR TRIM(CAST(t.SECONDARY_RECRUITER AS STRING))=''), COALESCE(s.SECONDARY_RECRUITER, t.SECONDARY_RECRUITER), t.SECONDARY_RECRUITER),
  SECONDARY_RECRUITER_EMP_NO = IF((t.SECONDARY_RECRUITER_EMP_NO IS NULL OR TRIM(CAST(t.SECONDARY_RECRUITER_EMP_NO AS STRING))=''), COALESCE(s.SECONDARY_RECRUITER_EMP_NO, t.SECONDARY_RECRUITER_EMP_NO), t.SECONDARY_RECRUITER_EMP_NO),
  ENTITY = IF((t.ENTITY IS NULL OR TRIM(CAST(t.ENTITY AS STRING))=''), COALESCE(s.ENTITY, t.ENTITY), t.ENTITY),
  FIFTYTWO_TENURE_RTO_LASTDATE = IF((t.FIFTYTWO_TENURE_RTO_LASTDATE IS NULL OR TRIM(CAST(t.FIFTYTWO_TENURE_RTO_LASTDATE AS STRING))=''), COALESCE(s.FIFTYTWO_TENURE_RTO_LASTDATE, t.FIFTYTWO_TENURE_RTO_LASTDATE), t.FIFTYTWO_TENURE_RTO_LASTDATE),
  FIFTYTWO_TENURE_CANDIDATE_STATUS = IF((t.FIFTYTWO_TENURE_CANDIDATE_STATUS IS NULL OR TRIM(CAST(t.FIFTYTWO_TENURE_CANDIDATE_STATUS AS STRING))=''), COALESCE(s.FIFTYTWO_TENURE_CANDIDATE_STATUS, t.FIFTYTWO_TENURE_CANDIDATE_STATUS), t.FIFTYTWO_TENURE_CANDIDATE_STATUS),
  ST_DT_PUSHBACK_REASON = IF((t.ST_DT_PUSHBACK_REASON IS NULL OR TRIM(CAST(t.ST_DT_PUSHBACK_REASON AS STRING))=''), COALESCE(s.ST_DT_PUSHBACK_REASON, t.ST_DT_PUSHBACK_REASON), t.ST_DT_PUSHBACK_REASON),
  CLIENT_NAME_IN_CONREP = IF((t.CLIENT_NAME_IN_CONREP IS NULL OR TRIM(CAST(t.CLIENT_NAME_IN_CONREP AS STRING))=''), COALESCE(s.CLIENT_NAME_IN_CONREP, t.CLIENT_NAME_IN_CONREP), t.CLIENT_NAME_IN_CONREP),
  BACKOUT_OR_TERMINATION = IF((t.BACKOUT_OR_TERMINATION IS NULL OR TRIM(CAST(t.BACKOUT_OR_TERMINATION AS STRING))=''), COALESCE(s.BACKOUT_OR_TERMINATION, t.BACKOUT_OR_TERMINATION), t.BACKOUT_OR_TERMINATION),
  COMMENTS = IF((t.COMMENTS IS NULL OR TRIM(CAST(t.COMMENTS AS STRING))=''), COALESCE(s.COMMENTS, t.COMMENTS), t.COMMENTS),
  TYPE_OF_CLIENT = IF((t.TYPE_OF_CLIENT IS NULL OR TRIM(CAST(t.TYPE_OF_CLIENT AS STRING))=''), COALESCE(s.TYPE_OF_CLIENT, t.TYPE_OF_CLIENT), t.TYPE_OF_CLIENT),
  WEEKLY_WALLET_MONEY = IF((t.WEEKLY_WALLET_MONEY IS NULL OR TRIM(CAST(t.WEEKLY_WALLET_MONEY AS STRING))=''), COALESCE(s.WEEKLY_WALLET_MONEY, t.WEEKLY_WALLET_MONEY), t.WEEKLY_WALLET_MONEY),
  DIVERSITY_STATUS = IF((t.DIVERSITY_STATUS IS NULL OR TRIM(CAST(t.DIVERSITY_STATUS AS STRING))=''), COALESCE(s.DIVERSITY_STATUS, t.DIVERSITY_STATUS), t.DIVERSITY_STATUS),
  PO_RECEIVED = IF((t.PO_RECEIVED IS NULL OR TRIM(CAST(t.PO_RECEIVED AS STRING))=''), COALESCE(s.PO_RECEIVED, t.PO_RECEIVED), t.PO_RECEIVED),
  PAYLOCITY_ID = IF((t.PAYLOCITY_ID IS NULL OR TRIM(CAST(t.PAYLOCITY_ID AS STRING))=''), COALESCE(s.PAYLOCITY_ID, t.PAYLOCITY_ID), t.PAYLOCITY_ID),
  BGC_CATEGORY1 = IF((t.BGC_CATEGORY1 IS NULL OR TRIM(CAST(t.BGC_CATEGORY1 AS STRING))=''), COALESCE(s.BGC_CATEGORY1, t.BGC_CATEGORY1), t.BGC_CATEGORY1),
  BGC_AMOUNT1 = IF((t.BGC_AMOUNT1 IS NULL OR TRIM(CAST(t.BGC_AMOUNT1 AS STRING))=''), COALESCE(s.BGC_AMOUNT1, t.BGC_AMOUNT1), t.BGC_AMOUNT1),
  BGC_CATEGORY2 = IF((t.BGC_CATEGORY2 IS NULL OR TRIM(CAST(t.BGC_CATEGORY2 AS STRING))=''), COALESCE(s.BGC_CATEGORY2, t.BGC_CATEGORY2), t.BGC_CATEGORY2),
  BGC_AMOUNT2 = IF((t.BGC_AMOUNT2 IS NULL OR TRIM(CAST(t.BGC_AMOUNT2 AS STRING))=''), COALESCE(s.BGC_AMOUNT2, t.BGC_AMOUNT2), t.BGC_AMOUNT2),
  BGC_CATEGORY3 = IF((t.BGC_CATEGORY3 IS NULL OR TRIM(CAST(t.BGC_CATEGORY3 AS STRING))=''), COALESCE(s.BGC_CATEGORY3, t.BGC_CATEGORY3), t.BGC_CATEGORY3),
  BGC_AMOUNT3 = IF((t.BGC_AMOUNT3 IS NULL OR TRIM(CAST(t.BGC_AMOUNT3 AS STRING))=''), COALESCE(s.BGC_AMOUNT3, t.BGC_AMOUNT3), t.BGC_AMOUNT3),
  BGC_TOTAL_BGV_COST = IF((t.BGC_TOTAL_BGV_COST IS NULL OR TRIM(CAST(t.BGC_TOTAL_BGV_COST AS STRING))=''), COALESCE(s.BGC_TOTAL_BGV_COST, t.BGC_TOTAL_BGV_COST), t.BGC_TOTAL_BGV_COST),
  BGC_AGENCY_NAME = IF((t.BGC_AGENCY_NAME IS NULL OR TRIM(CAST(t.BGC_AGENCY_NAME AS STRING))=''), COALESCE(s.BGC_AGENCY_NAME, t.BGC_AGENCY_NAME), t.BGC_AGENCY_NAME),
  ONB_CAND_DOB = IF((t.ONB_CAND_DOB IS NULL OR TRIM(CAST(t.ONB_CAND_DOB AS STRING))=''), COALESCE(s.ONB_CAND_DOB, t.ONB_CAND_DOB), t.ONB_CAND_DOB),
  ONB_I9_RECIEVED = IF((t.ONB_I9_RECIEVED IS NULL OR TRIM(CAST(t.ONB_I9_RECIEVED AS STRING))=''), COALESCE(s.ONB_I9_RECIEVED, t.ONB_I9_RECIEVED), t.ONB_I9_RECIEVED),
  ONB_E_VERIFY = IF((t.ONB_E_VERIFY IS NULL OR TRIM(CAST(t.ONB_E_VERIFY AS STRING))=''), COALESCE(s.ONB_E_VERIFY, t.ONB_E_VERIFY), t.ONB_E_VERIFY),
  ONB_SUPP_DOC1 = IF((t.ONB_SUPP_DOC1 IS NULL OR TRIM(CAST(t.ONB_SUPP_DOC1 AS STRING))=''), COALESCE(s.ONB_SUPP_DOC1, t.ONB_SUPP_DOC1), t.ONB_SUPP_DOC1),
  ONB_SUPP_DOC1_EXP_DT = IF((t.ONB_SUPP_DOC1_EXP_DT IS NULL OR TRIM(CAST(t.ONB_SUPP_DOC1_EXP_DT AS STRING))=''), COALESCE(s.ONB_SUPP_DOC1_EXP_DT, t.ONB_SUPP_DOC1_EXP_DT), t.ONB_SUPP_DOC1_EXP_DT),
  ONB_SUPP_DOC2 = IF((t.ONB_SUPP_DOC2 IS NULL OR TRIM(CAST(t.ONB_SUPP_DOC2 AS STRING))=''), COALESCE(s.ONB_SUPP_DOC2, t.ONB_SUPP_DOC2), t.ONB_SUPP_DOC2),
  ONB_SUPP_DOC2_EXP_DT = IF((t.ONB_SUPP_DOC2_EXP_DT IS NULL OR TRIM(CAST(t.ONB_SUPP_DOC2_EXP_DT AS STRING))=''), COALESCE(s.ONB_SUPP_DOC2_EXP_DT, t.ONB_SUPP_DOC2_EXP_DT), t.ONB_SUPP_DOC2_EXP_DT)
FROM (
  SELECT m.pid,
    COALESCE(IF(h.SKU_NUMBER IS NULL OR TRIM(CAST(h.SKU_NUMBER AS STRING))='', NULL, h.SKU_NUMBER), IF(r.SKU_NUMBER IS NULL OR TRIM(CAST(r.SKU_NUMBER AS STRING))='', NULL, r.SKU_NUMBER)) AS SKU_NUMBER,
    COALESCE(IF(h.CLIENT_RECRUITER IS NULL OR TRIM(CAST(h.CLIENT_RECRUITER AS STRING))='', NULL, h.CLIENT_RECRUITER), IF(r.CLIENT_RECRUITER IS NULL OR TRIM(CAST(r.CLIENT_RECRUITER AS STRING))='', NULL, r.CLIENT_RECRUITER)) AS CLIENT_RECRUITER,
    COALESCE(IF(h.CREDENTIALING_SPECIALIST IS NULL OR TRIM(CAST(h.CREDENTIALING_SPECIALIST AS STRING))='', NULL, h.CREDENTIALING_SPECIALIST), IF(r.CREDENTIALING_SPECIALIST IS NULL OR TRIM(CAST(r.CREDENTIALING_SPECIALIST AS STRING))='', NULL, r.CREDENTIALING_SPECIALIST)) AS CREDENTIALING_SPECIALIST,
    COALESCE(IF(h.CREDENTIALING_LEAD IS NULL OR TRIM(CAST(h.CREDENTIALING_LEAD AS STRING))='', NULL, h.CREDENTIALING_LEAD), IF(r.CREDENTIALING_LEAD IS NULL OR TRIM(CAST(r.CREDENTIALING_LEAD AS STRING))='', NULL, r.CREDENTIALING_LEAD)) AS CREDENTIALING_LEAD,
    COALESCE(IF(h.PRIMARY_SALES_PERSON IS NULL OR TRIM(CAST(h.PRIMARY_SALES_PERSON AS STRING))='', NULL, h.PRIMARY_SALES_PERSON), IF(r.PRIMARY_SALES_PERSON IS NULL OR TRIM(CAST(r.PRIMARY_SALES_PERSON AS STRING))='', NULL, r.PRIMARY_SALES_PERSON)) AS PRIMARY_SALES_PERSON,
    COALESCE(IF(h.SECONDARY_SALES_PERSON IS NULL OR TRIM(CAST(h.SECONDARY_SALES_PERSON AS STRING))='', NULL, h.SECONDARY_SALES_PERSON), IF(r.SECONDARY_SALES_PERSON IS NULL OR TRIM(CAST(r.SECONDARY_SALES_PERSON AS STRING))='', NULL, r.SECONDARY_SALES_PERSON)) AS SECONDARY_SALES_PERSON,
    COALESCE(IF(h.RECRUITMENT_MENTOR IS NULL OR TRIM(CAST(h.RECRUITMENT_MENTOR AS STRING))='', NULL, h.RECRUITMENT_MENTOR), IF(r.RECRUITMENT_MENTOR IS NULL OR TRIM(CAST(r.RECRUITMENT_MENTOR AS STRING))='', NULL, r.RECRUITMENT_MENTOR)) AS RECRUITMENT_MENTOR,
    COALESCE(IF(h.INVOICE_CYCLE_TO_CLIENT IS NULL OR TRIM(CAST(h.INVOICE_CYCLE_TO_CLIENT AS STRING))='', NULL, h.INVOICE_CYCLE_TO_CLIENT), IF(r.INVOICE_CYCLE_TO_CLIENT IS NULL OR TRIM(CAST(r.INVOICE_CYCLE_TO_CLIENT AS STRING))='', NULL, r.INVOICE_CYCLE_TO_CLIENT)) AS INVOICE_CYCLE_TO_CLIENT,
    COALESCE(IF(h.CLIENT_PAYMENT_TERMS IS NULL OR TRIM(CAST(h.CLIENT_PAYMENT_TERMS AS STRING))='', NULL, h.CLIENT_PAYMENT_TERMS), IF(r.CLIENT_PAYMENT_TERMS IS NULL OR TRIM(CAST(r.CLIENT_PAYMENT_TERMS AS STRING))='', NULL, r.CLIENT_PAYMENT_TERMS)) AS CLIENT_PAYMENT_TERMS,
    COALESCE(IF(h.CANDIDATE_PAYMENT_TERMS IS NULL OR TRIM(CAST(h.CANDIDATE_PAYMENT_TERMS AS STRING))='', NULL, h.CANDIDATE_PAYMENT_TERMS), IF(r.CANDIDATE_PAYMENT_TERMS IS NULL OR TRIM(CAST(r.CANDIDATE_PAYMENT_TERMS AS STRING))='', NULL, r.CANDIDATE_PAYMENT_TERMS)) AS CANDIDATE_PAYMENT_TERMS,
    COALESCE(IF(h.SECONDARY_RECRUITER IS NULL OR TRIM(CAST(h.SECONDARY_RECRUITER AS STRING))='', NULL, h.SECONDARY_RECRUITER), IF(r.SECONDARY_RECRUITER IS NULL OR TRIM(CAST(r.SECONDARY_RECRUITER AS STRING))='', NULL, r.SECONDARY_RECRUITER)) AS SECONDARY_RECRUITER,
    COALESCE(IF(h.SECONDARY_RECRUITER_EMP_NO IS NULL OR TRIM(CAST(h.SECONDARY_RECRUITER_EMP_NO AS STRING))='', NULL, h.SECONDARY_RECRUITER_EMP_NO), IF(r.SECONDARY_RECRUITER_EMP_NO IS NULL OR TRIM(CAST(r.SECONDARY_RECRUITER_EMP_NO AS STRING))='', NULL, r.SECONDARY_RECRUITER_EMP_NO)) AS SECONDARY_RECRUITER_EMP_NO,
    COALESCE(IF(h.ENTITY IS NULL OR TRIM(CAST(h.ENTITY AS STRING))='', NULL, h.ENTITY), IF(r.ENTITY IS NULL OR TRIM(CAST(r.ENTITY AS STRING))='', NULL, r.ENTITY)) AS ENTITY,
    COALESCE(IF(h.FIFTYTWO_TENURE_RTO_LASTDATE IS NULL OR TRIM(CAST(h.FIFTYTWO_TENURE_RTO_LASTDATE AS STRING))='', NULL, h.FIFTYTWO_TENURE_RTO_LASTDATE), IF(r.FIFTYTWO_TENURE_RTO_LASTDATE IS NULL OR TRIM(CAST(r.FIFTYTWO_TENURE_RTO_LASTDATE AS STRING))='', NULL, r.FIFTYTWO_TENURE_RTO_LASTDATE)) AS FIFTYTWO_TENURE_RTO_LASTDATE,
    COALESCE(IF(h.FIFTYTWO_TENURE_CANDIDATE_STATUS IS NULL OR TRIM(CAST(h.FIFTYTWO_TENURE_CANDIDATE_STATUS AS STRING))='', NULL, h.FIFTYTWO_TENURE_CANDIDATE_STATUS), IF(r.FIFTYTWO_TENURE_CANDIDATE_STATUS IS NULL OR TRIM(CAST(r.FIFTYTWO_TENURE_CANDIDATE_STATUS AS STRING))='', NULL, r.FIFTYTWO_TENURE_CANDIDATE_STATUS)) AS FIFTYTWO_TENURE_CANDIDATE_STATUS,
    IF(h.ST_DT_PUSHBACK_REASON IS NULL OR TRIM(CAST(h.ST_DT_PUSHBACK_REASON AS STRING))='', NULL, h.ST_DT_PUSHBACK_REASON) AS ST_DT_PUSHBACK_REASON,
    IF(h.CLIENT_NAME_IN_CONREP IS NULL OR TRIM(CAST(h.CLIENT_NAME_IN_CONREP AS STRING))='', NULL, h.CLIENT_NAME_IN_CONREP) AS CLIENT_NAME_IN_CONREP,
    IF(h.BACKOUT_OR_TERMINATION IS NULL OR TRIM(CAST(h.BACKOUT_OR_TERMINATION AS STRING))='', NULL, h.BACKOUT_OR_TERMINATION) AS BACKOUT_OR_TERMINATION,
    IF(h.COMMENTS IS NULL OR TRIM(CAST(h.COMMENTS AS STRING))='', NULL, h.COMMENTS) AS COMMENTS,
    COALESCE(IF(h.TYPE_OF_CLIENT IS NULL OR TRIM(CAST(h.TYPE_OF_CLIENT AS STRING))='', NULL, h.TYPE_OF_CLIENT), IF(r.TYPE_OF_CLIENT IS NULL OR TRIM(CAST(r.TYPE_OF_CLIENT AS STRING))='', NULL, r.TYPE_OF_CLIENT)) AS TYPE_OF_CLIENT,
    COALESCE(IF(h.WEEKLY_WALLET_MONEY IS NULL OR TRIM(CAST(h.WEEKLY_WALLET_MONEY AS STRING))='', NULL, h.WEEKLY_WALLET_MONEY), IF(r.WEEKLY_WALLET_MONEY IS NULL OR TRIM(CAST(r.WEEKLY_WALLET_MONEY AS STRING))='', NULL, r.WEEKLY_WALLET_MONEY)) AS WEEKLY_WALLET_MONEY,
    COALESCE(IF(h.DIVERSITY_STATUS IS NULL OR TRIM(CAST(h.DIVERSITY_STATUS AS STRING))='', NULL, h.DIVERSITY_STATUS), IF(r.DIVERSITY_STATUS IS NULL OR TRIM(CAST(r.DIVERSITY_STATUS AS STRING))='', NULL, r.DIVERSITY_STATUS)) AS DIVERSITY_STATUS,
    COALESCE(IF(h.PO_RECEIVED IS NULL OR TRIM(CAST(h.PO_RECEIVED AS STRING))='', NULL, h.PO_RECEIVED), IF(r.PO_RECEIVED IS NULL OR TRIM(CAST(r.PO_RECEIVED AS STRING))='', NULL, r.PO_RECEIVED)) AS PO_RECEIVED,
    COALESCE(IF(h.PAYLOCITY_ID IS NULL OR TRIM(CAST(h.PAYLOCITY_ID AS STRING))='', NULL, h.PAYLOCITY_ID), IF(r.PAYLOCITY_ID IS NULL OR TRIM(CAST(r.PAYLOCITY_ID AS STRING))='', NULL, r.PAYLOCITY_ID)) AS PAYLOCITY_ID,
    COALESCE(IF(h.BGC_CATEGORY1 IS NULL OR TRIM(CAST(h.BGC_CATEGORY1 AS STRING))='', NULL, h.BGC_CATEGORY1), IF(r.BGC_CATEGORY1 IS NULL OR TRIM(CAST(r.BGC_CATEGORY1 AS STRING))='', NULL, r.BGC_CATEGORY1)) AS BGC_CATEGORY1,
    COALESCE(IF(h.BGC_AMOUNT1 IS NULL OR TRIM(CAST(h.BGC_AMOUNT1 AS STRING))='', NULL, h.BGC_AMOUNT1), IF(r.BGC_AMOUNT1 IS NULL OR TRIM(CAST(r.BGC_AMOUNT1 AS STRING))='', NULL, r.BGC_AMOUNT1)) AS BGC_AMOUNT1,
    COALESCE(IF(h.BGC_CATEGORY2 IS NULL OR TRIM(CAST(h.BGC_CATEGORY2 AS STRING))='', NULL, h.BGC_CATEGORY2), IF(r.BGC_CATEGORY2 IS NULL OR TRIM(CAST(r.BGC_CATEGORY2 AS STRING))='', NULL, r.BGC_CATEGORY2)) AS BGC_CATEGORY2,
    COALESCE(IF(h.BGC_AMOUNT2 IS NULL OR TRIM(CAST(h.BGC_AMOUNT2 AS STRING))='', NULL, h.BGC_AMOUNT2), IF(r.BGC_AMOUNT2 IS NULL OR TRIM(CAST(r.BGC_AMOUNT2 AS STRING))='', NULL, r.BGC_AMOUNT2)) AS BGC_AMOUNT2,
    COALESCE(IF(h.BGC_CATEGORY3 IS NULL OR TRIM(CAST(h.BGC_CATEGORY3 AS STRING))='', NULL, h.BGC_CATEGORY3), IF(r.BGC_CATEGORY3 IS NULL OR TRIM(CAST(r.BGC_CATEGORY3 AS STRING))='', NULL, r.BGC_CATEGORY3)) AS BGC_CATEGORY3,
    COALESCE(IF(h.BGC_AMOUNT3 IS NULL OR TRIM(CAST(h.BGC_AMOUNT3 AS STRING))='', NULL, h.BGC_AMOUNT3), IF(r.BGC_AMOUNT3 IS NULL OR TRIM(CAST(r.BGC_AMOUNT3 AS STRING))='', NULL, r.BGC_AMOUNT3)) AS BGC_AMOUNT3,
    COALESCE(IF(h.BGC_TOTAL_BGV_COST IS NULL OR TRIM(CAST(h.BGC_TOTAL_BGV_COST AS STRING))='', NULL, h.BGC_TOTAL_BGV_COST), IF(r.BGC_TOTAL_BGV_COST IS NULL OR TRIM(CAST(r.BGC_TOTAL_BGV_COST AS STRING))='', NULL, r.BGC_TOTAL_BGV_COST)) AS BGC_TOTAL_BGV_COST,
    COALESCE(IF(h.BGC_AGENCY_NAME IS NULL OR TRIM(CAST(h.BGC_AGENCY_NAME AS STRING))='', NULL, h.BGC_AGENCY_NAME), IF(r.BGC_AGENCY_NAME IS NULL OR TRIM(CAST(r.BGC_AGENCY_NAME AS STRING))='', NULL, r.BGC_AGENCY_NAME)) AS BGC_AGENCY_NAME,
    COALESCE(IF(h.ONB_CAND_DOB IS NULL OR TRIM(CAST(h.ONB_CAND_DOB AS STRING))='', NULL, h.ONB_CAND_DOB), IF(r.ONB_CAND_DOB IS NULL OR TRIM(CAST(r.ONB_CAND_DOB AS STRING))='', NULL, r.ONB_CAND_DOB)) AS ONB_CAND_DOB,
    COALESCE(IF(h.ONB_I9_RECIEVED IS NULL OR TRIM(CAST(h.ONB_I9_RECIEVED AS STRING))='', NULL, h.ONB_I9_RECIEVED), IF(r.ONB_I9_RECIEVED IS NULL OR TRIM(CAST(r.ONB_I9_RECIEVED AS STRING))='', NULL, r.ONB_I9_RECIEVED)) AS ONB_I9_RECIEVED,
    COALESCE(IF(h.ONB_E_VERIFY IS NULL OR TRIM(CAST(h.ONB_E_VERIFY AS STRING))='', NULL, h.ONB_E_VERIFY), IF(r.ONB_E_VERIFY IS NULL OR TRIM(CAST(r.ONB_E_VERIFY AS STRING))='', NULL, r.ONB_E_VERIFY)) AS ONB_E_VERIFY,
    COALESCE(IF(h.ONB_SUPP_DOC1 IS NULL OR TRIM(CAST(h.ONB_SUPP_DOC1 AS STRING))='', NULL, h.ONB_SUPP_DOC1), IF(r.ONB_SUPP_DOC1 IS NULL OR TRIM(CAST(r.ONB_SUPP_DOC1 AS STRING))='', NULL, r.ONB_SUPP_DOC1)) AS ONB_SUPP_DOC1,
    COALESCE(IF(h.ONB_SUPP_DOC1_EXP_DT IS NULL OR TRIM(CAST(h.ONB_SUPP_DOC1_EXP_DT AS STRING))='', NULL, h.ONB_SUPP_DOC1_EXP_DT), IF(r.ONB_SUPP_DOC1_EXP_DT IS NULL OR TRIM(CAST(r.ONB_SUPP_DOC1_EXP_DT AS STRING))='', NULL, r.ONB_SUPP_DOC1_EXP_DT)) AS ONB_SUPP_DOC1_EXP_DT,
    COALESCE(IF(h.ONB_SUPP_DOC2 IS NULL OR TRIM(CAST(h.ONB_SUPP_DOC2 AS STRING))='', NULL, h.ONB_SUPP_DOC2), IF(r.ONB_SUPP_DOC2 IS NULL OR TRIM(CAST(r.ONB_SUPP_DOC2 AS STRING))='', NULL, r.ONB_SUPP_DOC2)) AS ONB_SUPP_DOC2,
    COALESCE(IF(h.ONB_SUPP_DOC2_EXP_DT IS NULL OR TRIM(CAST(h.ONB_SUPP_DOC2_EXP_DT AS STRING))='', NULL, h.ONB_SUPP_DOC2_EXP_DT), IF(r.ONB_SUPP_DOC2_EXP_DT IS NULL OR TRIM(CAST(r.ONB_SUPP_DOC2_EXP_DT AS STRING))='', NULL, r.ONB_SUPP_DOC2_EXP_DT)) AS ONB_SUPP_DOC2_EXP_DT
  FROM `cynetdatabase.rr_project_data.fix_20261123_ext_overwrite_cid_map` m
  LEFT JOIN `cynetdatabase.rr_project_data.all_CH_Deal_sheet_data` h ON CAST(h.PLACEMENT_ID AS STRING) = m.pid
  LEFT JOIN `cynetdatabase.rr_project_data.all_CH_data_runrate` r ON r.CONTRACT_ID = m.keep_id
) s
WHERE CAST(t.PLACEMENT_ID AS STRING) = s.pid
  AND t.CONTRACT_ID = (SELECT keep_id FROM `cynetdatabase.rr_project_data.fix_20261123_ext_overwrite_cid_map` mm WHERE mm.pid = s.pid);

